<script setup>
import{onMounted,reactive,ref}from'vue';import{publicEvaluationApi as api}from'../../publicEvaluationApi'
const orgs=ref([]),items=ref([]),history=ref([]),message=ref(''),image=ref(null),showItem=ref(false)
const form=reactive({orgUnitId:'',serviceItemId:'',convenienceScore:5,attitudeScore:5,timelinessScore:5,clarityScore:5,commentText:'',anonymous:true,evaluatorName:'',evaluatorPhone:'',evaluatorIdNo:''})
const item=reactive({id:null,itemCode:'',itemName:'',orgUnitId:'',description:'',status:'ACTIVE'})
async function load(){try{const [o,i,h]=await Promise.all([api.orgs(),api.items(),api.list({source:'LOCAL',size:20})]);orgs.value=o;items.value=i;history.value=h.items}catch(e){message.value=e.message}}
function editItem(x=null){Object.assign(item,x?{id:x.id,itemCode:x.item_code,itemName:x.item_name,orgUnitId:x.org_unit_id,description:x.description,status:x.status}:{id:null,itemCode:'',itemName:'',orgUnitId:'',description:'',status:'ACTIVE'});showItem.value=true}
async function saveItem(){try{await api.saveItem(item.id,{...item});showItem.value=false;await load()}catch(e){message.value=e.message}}
async function submit(){try{const r=await api.submit({...form},image.value);message.value=`评价 ${r.evaluation_no} 已保存`;Object.assign(form,{commentText:'',evaluatorName:'',evaluatorPhone:'',evaluatorIdNo:''});image.value=null;await load()}catch(e){message.value=e.message}}
onMounted(load)
</script>
<template><section class="page active"><div class="alert alert-info">本地群众评价入口：四项1～5星评分，支持匿名或实名提交，数据真实保存到SQLite。</div><div v-if="message" class="alert alert-success">{{message}}</div>
<div class="card"><div class="card-header"><h3>⭐ 政务服务评价</h3><button class="btn btn-outline" @click="editItem()">管理服务事项</button></div>
<div class="form-grid"><div class="form-item"><label>评价机构 *</label><select v-model="form.orgUnitId"><option value="">请选择</option><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.unit_name}}</option></select></div><div class="form-item"><label>服务事项 *</label><select v-model="form.serviceItemId"><option value="">请选择</option><option v-for="i in items.filter(x=>x.status==='ACTIVE'&&(!form.orgUnitId||x.org_unit_id==form.orgUnitId))" :key="i.id" :value="i.id">{{i.item_name}}</option></select></div>
<div v-for="[k,n] in [['convenienceScore','办事便捷度'],['attitudeScore','服务态度'],['timelinessScore','办结时效'],['clarityScore','政策告知清晰度']]" :key="k" class="form-item"><label>{{n}}</label><select v-model.number="form[k]"><option v-for="s in 5" :key="s" :value="s">{{s}} 星</option></select></div>
<div class="form-item full"><label>文字意见</label><textarea v-model="form.commentText" rows="3"></textarea></div><label><input v-model="form.anonymous" type="checkbox"> 匿名提交</label><template v-if="!form.anonymous"><div class="form-item"><label>姓名 *</label><input v-model="form.evaluatorName"></div><div class="form-item"><label>手机号</label><input v-model="form.evaluatorPhone"></div><div class="form-item"><label>身份证号</label><input v-model="form.evaluatorIdNo"></div></template><div class="form-item"><label>图片佐证（最大5MB）</label><input type="file" accept="image/*" @change="image=$event.target.files[0]"></div></div><button class="btn btn-primary" @click="submit">提交评价</button></div>
<div class="card"><div class="card-header"><h3>📋 本地评价历史</h3><button class="btn btn-outline" @click="load">刷新</button></div><table><thead><tr><th>编号</th><th>机构</th><th>事项</th><th>评分</th><th>评价人</th><th>时间</th></tr></thead><tbody><tr v-if="!history.length"><td colspan="6">暂无评价</td></tr><tr v-for="x in history" :key="x.id"><td>{{x.evaluation_no}}</td><td>{{x.unit_name}}</td><td>{{x.service_item_name}}</td><td>{{x.overall_score}}</td><td>{{x.masked_name}}</td><td>{{x.evaluated_at}}</td></tr></tbody></table></div>
<div v-if="showItem" class="modal-overlay" @click.self="showItem=false"><div class="modal"><div class="modal-header"><h3>服务事项</h3><button @click="showItem=false">×</button></div><div class="form-grid"><div class="form-item"><label>编码</label><input v-model="item.itemCode"></div><div class="form-item"><label>名称</label><input v-model="item.itemName"></div><div class="form-item"><label>机构</label><select v-model="item.orgUnitId"><option v-for="o in orgs" :key="o.id" :value="o.id">{{o.unit_name}}</option></select></div><div class="form-item"><label>状态</label><select v-model="item.status"><option value="ACTIVE">启用</option><option value="INACTIVE">停用</option></select></div><div class="form-item full"><label>说明</label><textarea v-model="item.description"></textarea></div></div><button class="btn btn-primary" @click="saveItem">保存</button><h4>现有事项</h4><div v-for="x in items" :key="x.id" class="log-item"><span>{{x.item_code}} {{x.item_name}} / {{x.unit_name}}</span><button class="btn btn-sm btn-outline" @click="editItem(x)">编辑</button></div></div></div>
</section></template>
<style scoped>.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:12px}.full{grid-column:1/-1}.modal-overlay{position:fixed;inset:0;background:#0006;z-index:1000;display:flex;align-items:center;justify-content:center}.modal{background:#fff;padding:22px;border-radius:12px;width:min(760px,94vw);max-height:88vh;overflow:auto}.modal-header{display:flex;justify-content:space-between}.modal-header button{border:0;background:none;font-size:25px}@media(max-width:700px){.form-grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
